<article class="detail"><div class="detail-media"><img src="<?= e($product['image'] ?: url('/assets/images/product-placeholder.svg')) ?>" alt="<?= e($product['name']) ?>"></div><div class="detail-copy"><p class="eyebrow"><?= e($product['brand_name'] ?: 'MORFINITY Originals') ?></p><h1><?= e($product['name']) ?></h1><p class="price"><?php if ($product['sale_price']): ?><span class="sale"><?= money($product['price']) ?></span><?php endif; ?><?= money($product['sale_price'] ?: $product['price']) ?></p><p><?= nl2br(e($product['description'])) ?></p>
<form method="post" action="<?= e(url('/cart/add')) ?>"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><div class="form-grid"><div class="field"><label for="size">Size</label><select id="size" name="size"><?php foreach (array_filter(array_map('trim', explode(',', $product['sizes']))) as $size): ?><option><?= e($size) ?></option><?php endforeach; ?></select></div><div class="field"><label for="quantity">Quantity</label><input id="quantity" type="number" name="quantity" min="1" max="<?= max(1,(int)$product['stock']) ?>" value="1"></div><div class="field full"><button <?= (int)$product['stock'] < 1 ? 'disabled' : '' ?>><?= (int)$product['stock'] < 1 ? 'Sold out' : 'Add to bag' ?></button></div></div></form><p class="muted">Colours: <?= e($product['colours']) ?> · Secure order-request checkout</p></div></article>

